1	/**
2	 * analyze-url — Edge Function (Orchestrator)
3	 *
4	 * Full CRO audit pipeline for a given URL.
5	 *
6	 * Pipeline:
7	 *   1. Auth + scan limit check
8	 *   2. Create scan record (status: analyzing)
9	 *   3. Screenshot + DOM scrape (Railway service or dev fallback)
10	 *   4. Upload screenshot to Supabase Storage
11	 *   5. AI Vision Analysis (Claude + screenshot)
12	 *   6. AI Text Analysis (Claude + DOM content)
13	 *   7. PageSpeed Analysis (Google API)
14	 *   8. Score + Save (insert scan_results, update scan)
15	 *   9. Return scan ID
16	 *
17	 * Required env vars:
18	 *   SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
19	 *   ANTHROPIC_API_KEY
20	 *   SCREENSHOT_SERVICE_URL (Railway service) — optional in dev
21	 *   SCREENSHOT_SERVICE_API_KEY — required if service URL is set
22	 *   PAGESPEED_API_KEY — Google Cloud API key
23	 *   SCREENSHOTONE_ACCESS_KEY — dev fallback screenshot service
24	 */
25	
26	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
27	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
28	import { buildVisionPrompt, buildTextPrompt, PageType } from "./prompts.ts";
29	import {
30	  calculateScoringOutput,
31	  sanitizeFinding,
32	  VisionAnalysisResult,
33	  TextAnalysisResult,
34	  PageSpeedResult,
35	  Finding,
36	} from "./scoring.ts";
37	
38	// ── CORS headers ──────────────────────────────────────────────
39	
40	const corsHeaders = {
41	  "Access-Control-Allow-Origin": "*",
42	  "Access-Control-Allow-Headers":
43	    "authorization, x-client-info, apikey, content-type",
44	  "Access-Control-Allow-Methods": "POST, OPTIONS",
45	};
46	
47	function corsResponse(body: unknown, status = 200) {
48	  return new Response(JSON.stringify(body), {
49	    status,
50	    headers: { ...corsHeaders, "Content-Type": "application/json" },
51	  });
52	}
53	
54	// ── DOM data shape from screenshot service ────────────────────
55	
56	interface DomData {
57	  headings: string[];
58	  cta_buttons: string[];
59	  images: Array<{ src: string; alt: string }>;
60	  meta_description: string;
61	  body_text: string;
62	  links: Array<{ text: string; href: string }>;
63	  forms: number;
64	  testimonials: string[];
65	  trust_badges: string[];
66	}
67	
68	interface ScreenshotServiceResponse {
69	  screenshot_base64: string;
70	  dom_data: DomData;
71	  page_title: string;
72	  favicon_url: string;
73	}
74	
75	// ── Main handler ──────────────────────────────────────────────
76	
77	serve(async (req: Request) => {
78	  // Preflight
79	  if (req.method === "OPTIONS") {
80	    return new Response("ok", { headers: corsHeaders });
81	  }
82	
83	  if (req.method !== "POST") {
84	    return corsResponse({ error: "Method not allowed" }, 405);
85	  }
86	
87	  // ── 1. Auth ─────────────────────────────────────────────────
88	  const authHeader = req.headers.get("Authorization");
89	  if (!authHeader?.startsWith("Bearer ")) {
90	    return corsResponse({ error: "Missing authorization header" }, 401);
91	  }
92	  const token = authHeader.replace("Bearer ", "").trim();
93	
94	  const supabase = createClient(
95	    Deno.env.get("SUPABASE_URL") ?? "",
96	    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
97	  );
98	
99	  const { data: { user }, error: authError } = await supabase.auth.getUser(token);
100	  if (!user || authError) {
101	    return corsResponse({ error: "Unauthorized" }, 401);
102	  }
103	
104	  // ── 2. Parse request body ────────────────────────────────────
105	  let url: string;
106	  let pageType: PageType;
107	  let existingScanId: string | undefined;
108	  try {
109	    const body = await req.json();
110	    url = body.url;
111	    pageType = body.page_type ?? "other";
112	    existingScanId = typeof body.scan_id === "string" ? body.scan_id : undefined;
113	    if (!url || typeof url !== "string") {
114	      return corsResponse({ error: "url is required" }, 400);
115	    }
116	    // Normalize URL
117	    if (!url.startsWith("http://") && !url.startsWith("https://")) {
118	      url = `https://${url}`;
119	    }
120	    new URL(url); // validate format — throws if invalid
121	  } catch (_e) {
122	    return corsResponse({ error: "Invalid request body or URL" }, 400);
123	  }
124	
125	  // ── 3. Check scan limit ──────────────────────────────────────
126	  const { data: allowed, error: limitError } = await supabase.rpc(
127	    "increment_scan_usage",
128	    { user_uuid: user.id },
129	  );
130	  if (limitError || !allowed) {
131	    // Clean up the pending scan row the frontend already created
132	    if (existingScanId) {
133	      await supabase
134	        .from("scans")
135	        .update({ status: "failed", error_message: "Scan limit reached" })
136	        .eq("id", existingScanId)
137	        .eq("user_id", user.id);
138	    }
139	    return corsResponse(
140	      { error: "Scan limit reached. Upgrade your plan to continue." },
141	      429,
142	    );
143	  }
144	
145	  // ── 4. Use existing scan record or create a new one ──────────
146	  let scanId: string;
147	
148	  if (existingScanId) {
149	    // Update the frontend-created pending scan to analyzing
150	    const { error: updateError } = await supabase
151	      .from("scans")
152	      .update({ status: "analyzing", device: "both" })
153	      .eq("id", existingScanId)
154	      .eq("user_id", user.id);
155	
156	    if (updateError) {
157	      console.error("Failed to update scan record:", updateError);
158	      return corsResponse({ error: "Failed to initiate scan" }, 500);
159	    }
160	    scanId = existingScanId;
161	  } else {
162	    // Fallback: create scan record (backwards compatibility / direct API calls)
163	    const { data: scan, error: scanInsertError } = await supabase
164	      .from("scans")
165	      .insert({
166	        user_id: user.id,
167	        url,
168	        page_type: pageType,
169	        status: "analyzing",
170	        device: "both",
171	      })
172	      .select("id")
173	      .single();
174	
175	    if (scanInsertError || !scan) {
176	      console.error("Failed to create scan record:", scanInsertError);
177	      return corsResponse({ error: "Failed to initiate scan" }, 500);
178	    }
179	    scanId = scan.id;
180	  }
181	
182	  // All subsequent errors must update scan status to failed
183	  const failScan = async (message: string) => {
184	    await supabase
185	      .from("scans")
186	      .update({ status: "failed", error_message: message })
187	      .eq("id", scanId);
188	  };
189	
190	  try {
191	    // ── 5. Screenshot + Scrape ─────────────────────────────────
192	    let screenshotData: ScreenshotServiceResponse;
193	    try {
194	      screenshotData = await captureScreenshot(url);
195	    } catch (e) {
196	      const msg = e instanceof Error ? e.message : "Screenshot capture failed";
197	      await failScan(msg);
198	      return corsResponse({ error: msg }, 500);
199	    }
200	
201	    // ── 6. Upload screenshot ───────────────────────────────────
202	    let screenshotUrl: string | null = null;
203	    if (screenshotData.screenshot_base64) {
204	      try {
205	        screenshotUrl = await uploadScreenshot(
206	          supabase,
207	          screenshotData.screenshot_base64,
208	          scanId,
209	        );
210	      } catch (e) {
211	        // Non-fatal — scan continues without screenshot
212	        console.warn("Screenshot upload failed:", e);
213	      }
214	    }
215	
216	    // Update scan with page metadata from screenshot service
217	    await supabase
218	      .from("scans")
219	      .update({
220	        page_title: screenshotData.page_title || null,
221	        favicon_url: screenshotData.favicon_url || null,
222	        screenshot_url: screenshotUrl,
223	      })
224	      .eq("id", scanId);
225	
226	    // ── 7. AI Vision Analysis ──────────────────────────────────
227	    let visionResult: VisionAnalysisResult;
228	    try {
229	      visionResult = await runVisionAnalysis(
230	        screenshotData.screenshot_base64,
231	        pageType,
232	      );
233	    } catch (e) {
234	      const msg = e instanceof Error ? e.message : "AI vision analysis failed";
235	      await failScan(msg);
236	      return corsResponse({ error: msg }, 500);
237	    }
238	
239	    // ── 8. AI Text Analysis ────────────────────────────────────
240	    let textResult: TextAnalysisResult;
241	    try {
242	      textResult = await runTextAnalysis(screenshotData.dom_data, pageType);
243	    } catch (e) {
244	      const msg = e instanceof Error ? e.message : "AI text analysis failed";
245	      await failScan(msg);
246	      return corsResponse({ error: msg }, 500);
247	    }
248	
249	    // ── 9. PageSpeed Analysis ──────────────────────────────────
250	    let pageSpeedResult: PageSpeedResult;
251	    try {
252	      pageSpeedResult = await runPageSpeedAnalysis(url);
253	    } catch (e) {
254	      // Non-fatal — use fallback score
255	      console.warn("PageSpeed analysis failed, using fallback:", e);
256	      pageSpeedResult = buildPageSpeedFallback();
257	    }
258	
259	    // ── 10. Score + Save ───────────────────────────────────────
260	    const scoring = calculateScoringOutput(
261	      visionResult,
262	      textResult,
263	      pageSpeedResult,
264	      pageType,
265	      scanId,
266	    );
267	
268	    // Insert one row per pillar into scan_results
269	    const scanResultRows = scoring.pillar_results.map((pr) => ({
270	      scan_id: scanId,
271	      pillar: pr.pillar,
272	      score: pr.score,
273	      weight: pr.weight,
274	      benchmark: pr.benchmark,
275	      findings: pr.findings,
276	    }));
277	
278	    const { error: resultsError } = await supabase
279	      .from("scan_results")
280	      .insert(scanResultRows);
281	
282	    if (resultsError) {
283	      console.error("Failed to insert scan_results:", resultsError);
284	      await failScan("Failed to save analysis results");
285	      return corsResponse({ error: "Failed to save results" }, 500);
286	    }
287	
288	    // Update scan to completed
289	    const { error: updateError } = await supabase
290	      .from("scans")
291	      .update({
292	        status: "completed",
293	        overall_score: scoring.overall_score,
294	        issues_found: scoring.issues_found,
295	        critical_issues: scoring.critical_issues,
296	        warnings: scoring.warnings,
297	        quick_wins: scoring.quick_wins,
298	        completed_at: new Date().toISOString(),
299	      })
300	      .eq("id", scanId);
301	
302	    if (updateError) {
303	      console.error("Failed to update scan status:", updateError);
304	      // Results are saved — don't fail the whole scan
305	    }
306	
307	    // ── 11. Send scan complete email (fire-and-forget) ─────────────
308	    try {
309	      // Fetch user profile for name and email
310	      const [profileRes, emailRes] = await Promise.all([
311	        supabase
312	          .from("profiles")
313	          .select("full_name, company_name")
314	          .eq("id", user.id)
315	          .single(),
316	        supabase.auth.admin.getUserById(user.id),
317	      ]);
318	
319	      const userName = profileRes.data?.full_name ?? "there";
320	      const userEmail = emailRes.data?.user?.email;
321	
322	      if (userEmail) {
323	        await supabase.functions.invoke("send-email", {
324	          body: {
325	            type: "scan_complete",
326	            to: userEmail,
327	            data: {
328	              name: userName,
329	              url,
330	              score: scoring.overall_score,
331	              scan_id: scanId,
332	              critical_count: scoring.critical_issues,
333	              quick_wins: scoring.quick_wins,
334	            },
335	          },
336	        });
337	      }
338	    } catch (emailErr) {
339	      // Non-critical: never fail a scan because the notification email failed
340	      console.warn("Scan complete email failed (non-fatal):", emailErr);
341	    }
342	
343	    return corsResponse({ scan_id: scanId, overall_score: scoring.overall_score });
344	  } catch (error) {
345	    const msg = error instanceof Error ? error.message : "Unexpected error during scan";
346	    console.error("Unexpected scan error:", error);
347	    await failScan(msg);
348	    return corsResponse({ error: "Scan failed due to an unexpected error" }, 500);
349	  }
350	});
351	
352	// ── Screenshot + Scrape ───────────────────────────────────────
353	
354	async function captureScreenshot(url: string): Promise<ScreenshotServiceResponse> {
355	  const serviceUrl = Deno.env.get("SCREENSHOT_SERVICE_URL");
356	
357	  if (serviceUrl) {
358	    // Production: Railway Puppeteer service
359	    const apiKey = Deno.env.get("SCREENSHOT_SERVICE_API_KEY") ?? "";
360	    const res = await fetch(`${serviceUrl}/screenshot`, {
361	      method: "POST",
362	      headers: {
363	        "Content-Type": "application/json",
364	        "X-API-Key": apiKey,
365	      },
366	      body: JSON.stringify({ url, device: "desktop" }),
367	    });
368	
369	    if (!res.ok) {
370	      const text = await res.text();
371	      throw new Error(`Screenshot service error ${res.status}: ${text.slice(0, 200)}`);
372	    }
373	
374	    return await res.json() as ScreenshotServiceResponse;
375	  }
376	
377	  // Dev fallback: ScreenshotOne API + fetch DOM ourselves
378	  console.warn(
379	    "SCREENSHOT_SERVICE_URL not set — using dev fallback (ScreenshotOne + fetch).",
380	  );
381	  return await devFallbackCapture(url);
382	}
383	
384	async function devFallbackCapture(url: string): Promise<ScreenshotServiceResponse> {
385	  const accessKey = Deno.env.get("SCREENSHOTONE_ACCESS_KEY");
386	
387	  let screenshotBase64 = "";
388	  if (accessKey) {
389	    try {
390	      // ScreenshotOne free tier — returns base64 image
391	      const params = new URLSearchParams({
392	        access_key: accessKey,
393	        url,
394	        full_page: "true",
395	        viewport_width: "1280",
396	        viewport_height: "900",
397	        format: "jpg",
398	        image_quality: "80",
399	        response_type: "json",
400	      });
401	      const ssRes = await fetch(
402	        `https://api.screenshotone.com/take?${params.toString()}`,
403	      );
404	      if (ssRes.ok) {
405	        const ssJson = await ssRes.json();
406	        screenshotBase64 = ssJson.screenshot ?? "";
407	      }
408	    } catch (e) {
409	      console.warn("ScreenshotOne fallback failed:", e);
410	    }
411	  }
412	
413	  // Fetch raw HTML for DOM scraping
414	  const domData = await scrapeDomFromHtml(url);
415	
416	  return {
417	    screenshot_base64: screenshotBase64,
418	    dom_data: domData.domData,
419	    page_title: domData.pageTitle,
420	    favicon_url: domData.faviconUrl,
421	  };
422	}
423	
424	// ── Lightweight HTML scraper (dev fallback) ───────────────────
425	
426	async function scrapeDomFromHtml(url: string): Promise<{
427	  domData: DomData;
428	  pageTitle: string;
429	  faviconUrl: string;
430	}> {
431	  let html = "";
432	  try {
433	    const res = await fetch(url, {
434	      headers: {
435	        "User-Agent":
436	          "Mozilla/5.0 (compatible; CROBOT/1.0; +https://convertscn.com)",
437	        "Accept": "text/html,application/xhtml+xml",
438	      },
439	      signal: AbortSignal.timeout(15_000),
440	    });
441	    if (res.ok) {
442	      html = await res.text();
443	    }
444	  } catch (e) {
445	    console.warn("HTML fetch failed:", e);
446	    // Return empty DOM — AI will flag missing data as findings
447	  }
448	
449	  return parseHtml(html, url);
450	}
451	
452	function parseHtml(
453	  html: string,
454	  baseUrl: string,
455	): { domData: DomData; pageTitle: string; faviconUrl: string } {
456	  // Extract title
457	  const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
458	  const pageTitle = titleMatch ? decodeHtmlEntities(titleMatch[1].trim()) : "";
459	
460	  // Extract favicon
461	  const faviconMatch = html.match(
462	    /<link[^>]+rel=["'](?:shortcut )?icon["'][^>]+href=["']([^"']+)["']/i,
463	  ) ?? html.match(/<link[^>]+href=["']([^"']+)["'][^>]+rel=["'](?:shortcut )?icon["']/i);
464	  let faviconUrl = "";
465	  if (faviconMatch) {
466	    try {
467	      faviconUrl = new URL(faviconMatch[1], baseUrl).toString();
468	    } catch (_) {
469	      faviconUrl = faviconMatch[1];
470	    }
471	  }
472	
473	  // Extract meta description
474	  const metaMatch = html.match(
475	    /<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i,
476	  ) ?? html.match(
477	    /<meta[^>]+content=["']([^"']+)["'][^>]+name=["']description["']/i,
478	  );
479	  const metaDescription = metaMatch ? decodeHtmlEntities(metaMatch[1]) : "";
480	
481	  // Extract headings h1-h4
482	  const headings: string[] = [];
483	  const headingRegex = /<h([1-4])[^>]*>([\s\S]*?)<\/h\1>/gi;
484	  let hMatch;
485	  while ((hMatch = headingRegex.exec(html)) !== null && headings.length < 20) {
486	    const text = stripTags(hMatch[2]).trim();
487	    if (text) headings.push(text);
488	  }
489	
490	  // Extract buttons and links with CTA-like text
491	  const ctaButtons: string[] = [];
492	  const ctaKeywords = /\b(get|start|try|sign|join|buy|shop|order|book|schedule|download|learn|see|watch|explore|discover|request|contact|subscribe)\b/i;
493	  const buttonRegex = /<(?:button|a)[^>]*>([\s\S]*?)<\/(?:button|a)>/gi;
494	  let btnMatch;
495	  while ((btnMatch = buttonRegex.exec(html)) !== null && ctaButtons.length < 15) {
496	    const text = stripTags(btnMatch[1]).trim();
497	    if (text && text.length < 60 && ctaKeywords.test(text)) {
498	      ctaButtons.push(text);
499	    }
500	  }
501	
502	  // Extract images
503	  const images: Array<{ src: string; alt: string }> = [];
504	  const imgRegex = /<img[^>]+>/gi;
505	  let imgMatch;
506	  while ((imgMatch = imgRegex.exec(html)) !== null && images.length < 20) {
507	    const srcMatch = imgMatch[0].match(/src=["']([^"']+)["']/i);
508	    const altMatch = imgMatch[0].match(/alt=["']([^"']*)["']/i);
509	    if (srcMatch) {
510	      images.push({
511	        src: srcMatch[1],
512	        alt: altMatch ? altMatch[1] : "",
513	      });
514	    }
515	  }
516	
517	  // Extract links
518	  const links: Array<{ text: string; href: string }> = [];
519	  const linkRegex = /<a[^>]+href=["']([^"'#][^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi;
520	  let linkMatch;
521	  while ((linkMatch = linkRegex.exec(html)) !== null && links.length < 30) {
522	    const text = stripTags(linkMatch[2]).trim();
523	    if (text && text.length < 80) {
524	      links.push({ text, href: linkMatch[1] });
525	    }
526	  }
527	
528	  // Count forms
529	  const forms = (html.match(/<form[^>]*>/gi) ?? []).length;
530	
531	  // Heuristic: extract testimonial-like text blocks (blockquote or q tags)
532	  const testimonials: string[] = [];
533	  const quoteRegex = /<(?:blockquote|q)[^>]*>([\s\S]*?)<\/(?:blockquote|q)>/gi;
534	  let qMatch;
535	  while ((qMatch = quoteRegex.exec(html)) !== null && testimonials.length < 5) {
536	    const text = stripTags(qMatch[1]).trim();
537	    if (text && text.length > 30) testimonials.push(text.slice(0, 300));
538	  }
539	
540	  // Extract body text (strip scripts, styles, nav, footer first)
541	  let bodyText = html
542	    .replace(/<script[\s\S]*?<\/script>/gi, "")
543	    .replace(/<style[\s\S]*?<\/style>/gi, "")
544	    .replace(/<nav[\s\S]*?<\/nav>/gi, "")
545	    .replace(/<footer[\s\S]*?<\/footer>/gi, "")
546	    .replace(/<header[\s\S]*?<\/header>/gi, "");
547	  bodyText = stripTags(bodyText).replace(/\s+/g, " ").trim();
548	
549	  // Detect trust badges from common keywords
550	  const trustBadges: string[] = [];
551	  const badgeKeywords = [
552	    "SSL", "GDPR", "SOC 2", "ISO", "PCI", "HIPAA", "BBB",
553	    "Trustpilot", "G2", "Capterra", "Product Hunt", "4.8", "4.9", "5.0",
554	    "money-back guarantee", "100% satisfaction", "secure checkout",
555	    "verified", "certified", "award",
556	  ];
557	  for (const kw of badgeKeywords) {
558	    if (html.toLowerCase().includes(kw.toLowerCase())) {
559	      trustBadges.push(kw);
560	    }
561	  }
562	
563	  return {
564	    domData: {
565	      headings,
566	      cta_buttons: ctaButtons,
567	      images,
568	      meta_description: metaDescription,
569	      body_text: bodyText,
570	      links,
571	      forms,
572	      testimonials,
573	      trust_badges: trustBadges,
574	    },
575	    pageTitle,
576	    faviconUrl,
577	  };
578	}
579	
580	// ── Screenshot Upload ─────────────────────────────────────────
581	
582	async function uploadScreenshot(
583	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
584	  supabase: Record<string, any>,
585	  base64Data: string,
586	  scanId: string,
587	): Promise<string> {
588	  // Decode base64 to Uint8Array
589	  const binaryStr = atob(base64Data);
590	  const bytes = new Uint8Array(binaryStr.length);
591	  for (let i = 0; i < binaryStr.length; i++) {
592	    bytes[i] = binaryStr.charCodeAt(i);
593	  }
594	
595	  const path = `${scanId}/screenshot.jpg`;
596	  const { error } = await supabase.storage
597	    .from("screenshots")
598	    .upload(path, bytes, {
599	      contentType: "image/jpeg",
600	      upsert: true,
601	    });
602	
603	  if (error) throw new Error(`Storage upload failed: ${error.message}`);
604	
605	  const { data } = supabase.storage.from("screenshots").getPublicUrl(path);
606	  return data.publicUrl;
607	}
608	
609	// ── AI Vision Analysis ────────────────────────────────────────
610	
611	async function runVisionAnalysis(
612	  screenshotBase64: string,
613	  pageType: PageType,
614	): Promise<VisionAnalysisResult> {
615	  const anthropicKey = Deno.env.get("ANTHROPIC_API_KEY");
616	  if (!anthropicKey) throw new Error("ANTHROPIC_API_KEY is not configured");
617	
618	  const systemPrompt = buildVisionPrompt(pageType);
619	
620	  const messageContent: unknown[] = screenshotBase64
621	    ? [
622	        {
623	          type: "image",
624	          source: {
625	            type: "base64",
