170	
171	export function calculateScoringOutput(
172	  visionResult: VisionAnalysisResult,
173	  textResult: TextAnalysisResult,
174	  pageSpeedResult: PageSpeedResult,
175	  pageType: PageType,
176	  _scanId: string,
177	): ScoringOutput {
178	  const weights = PAGE_TYPE_WEIGHTS[pageType] ?? PAGE_TYPE_WEIGHTS.other;
179	
180	  // Merge CTA findings: vision CTA + any text CTA findings
181	  const ctaFindings: Finding[] = [
182	    ...(visionResult.cta_effectiveness?.findings ?? []),
183	  ];
184	  if (textResult.cta_effectiveness?.findings) {
185	    // Avoid duplicate finding IDs by prefixing text-sourced CTA findings
186	    const textCtaFindings = textResult.cta_effectiveness.findings.map((f) => ({
187	      ...f,
188	      id: f.id.startsWith("f_ct_copy") ? f.id : `f_ct_copy_${f.id}`,
189	    }));
190	    ctaFindings.push(...textCtaFindings);
191	  }
192	
193	  // Average CTA scores from both sources if text analysis included CTA
194	  let ctaScore = visionResult.cta_effectiveness?.score ?? 50;
195	  if (textResult.cta_effectiveness?.score !== undefined) {
196	    ctaScore = Math.round((ctaScore + textResult.cta_effectiveness.score) / 2);
197	  }
198	
199	  // Build pillar results array
200	  const pillarResults: PillarResult[] = [
201	    {
202	      pillar: "value_proposition",
203	      score: clampScore(textResult.value_proposition?.score ?? 50),
204	      weight: weights.value_proposition,
205	      benchmark: INDUSTRY_BENCHMARKS.value_proposition,
206	      findings: deduplicateFindings(textResult.value_proposition?.findings ?? []),
207	    },
208	    {
209	      pillar: "cta_effectiveness",
210	      score: clampScore(ctaScore),
211	      weight: weights.cta_effectiveness,
212	      benchmark: INDUSTRY_BENCHMARKS.cta_effectiveness,
213	      findings: deduplicateFindings(ctaFindings),
214	    },
215	    {
216	      pillar: "trust_signals",
217	      score: clampScore(visionResult.trust_signals?.score ?? 50),
218	      weight: weights.trust_signals,
219	      benchmark: INDUSTRY_BENCHMARKS.trust_signals,
220	      findings: deduplicateFindings(visionResult.trust_signals?.findings ?? []),
221	    },
222	    {
223	      pillar: "visual_hierarchy",
224	      score: clampScore(visionResult.visual_hierarchy?.score ?? 50),
225	      weight: weights.visual_hierarchy,
226	      benchmark: INDUSTRY_BENCHMARKS.visual_hierarchy,
227	      findings: deduplicateFindings(visionResult.visual_hierarchy?.findings ?? []),
228	    },
229	    {
230	      pillar: "mobile_experience",
231	      score: clampScore(visionResult.mobile_experience?.score ?? 50),
232	      weight: weights.mobile_experience,
233	      benchmark: INDUSTRY_BENCHMARKS.mobile_experience,
234	      findings: deduplicateFindings(visionResult.mobile_experience?.findings ?? []),
235	    },
236	    {
237	      pillar: "content_copy",
238	      score: clampScore(textResult.content_copy?.score ?? 50),
239	      weight: weights.content_copy,
240	      benchmark: INDUSTRY_BENCHMARKS.content_copy,
241	      findings: deduplicateFindings(textResult.content_copy?.findings ?? []),
242	    },
243	    {
244	      pillar: "page_performance",
245	      score: clampScore(pageSpeedResult.score),
246	      weight: weights.page_performance,
247	      benchmark: INDUSTRY_BENCHMARKS.page_performance,
248	      findings: deduplicateFindings(pageSpeedResult.findings),
249	    },
250	  ];
251	
252	  // Calculate weighted overall score
253	  let weightedSum = 0;
254	  let totalWeight = 0;
255	  for (const result of pillarResults) {
256	    weightedSum += result.score * result.weight;
257	    totalWeight += result.weight;
258	  }
259	  const overallScore = totalWeight > 0
260	    ? Math.round(weightedSum / totalWeight)
261	    : 0;
262	
263	  // Count issues across all pillars
264	  let issuesFound = 0;
265	  let criticalIssues = 0;
266	  let warnings = 0;
267	  let quickWins = 0;
268	
269	  for (const result of pillarResults) {
270	    for (const finding of result.findings) {
271	      if (finding.severity === "critical") {
272	        issuesFound++;
273	        criticalIssues++;
274	      } else if (finding.severity === "warning") {
275	        issuesFound++;
276	        warnings++;
277	      } else if (finding.severity === "info") {
278	        issuesFound++;
279	      }
280	      // "passed" findings don't count as issues
281	      if (
282	        finding.effort === "quick" &&
283	        finding.severity !== "passed" &&
284	        finding.severity !== "info"
285	      ) {
286	        quickWins++;
287	      }
288	    }
289	  }
290	
291	  return {
292	    overall_score: clampScore(overallScore),
293	    pillar_results: pillarResults,
294	    issues_found: issuesFound,
295	    critical_issues: criticalIssues,
296	    warnings,
297	    quick_wins: quickWins,
298	  };
299	}
