301	// ── Helpers ───────────────────────────────────────────────────
302	
303	function clampScore(score: number): number {
304	  return Math.max(0, Math.min(100, Math.round(score)));
305	}
306	
307	/** Removes findings with duplicate IDs, keeping first occurrence */
308	function deduplicateFindings(findings: Finding[]): Finding[] {
309	  const seen = new Set<string>();
310	  return findings.filter((f) => {
311	    if (seen.has(f.id)) return false;
312	    seen.add(f.id);
313	    return true;
314	  });
315	}
316	
317	/** Validates that a finding object has all required fields */
318	export function validateFinding(f: unknown): f is Finding {
319	  if (!f || typeof f !== "object") return false;
320	  const obj = f as Record<string, unknown>;
321	  return (
322	    typeof obj.id === "string" &&
323	    typeof obj.title === "string" &&
324	    typeof obj.severity === "string" &&
325	    ["critical", "warning", "info", "passed"].includes(obj.severity as string) &&
326	    typeof obj.current_state === "string" &&
327	    typeof obj.recommendation === "string" &&
328	    typeof obj.ai_suggestion === "string" &&
329	    typeof obj.is_premium === "boolean" &&
330	    typeof obj.effort === "string" &&
331	    ["quick", "moderate", "significant"].includes(obj.effort as string) &&
332	    typeof obj.estimated_lift === "string" &&
333	    typeof obj.category === "string"
334	  );
335	}
336	
337	/** Sanitizes a raw AI finding — fills missing fields with safe defaults */
338	export function sanitizeFinding(f: Record<string, unknown>, fallbackId: string): Finding {
339	  const severities: Severity[] = ["critical", "warning", "info", "passed"];
340	  const efforts: Effort[] = ["quick", "moderate", "significant"];
341	
342	  const rawSeverity = f.severity as string;
343	  const rawEffort = f.effort as string;
344	
345	  // Map AI response effort values to our Effort type
346	  // The AI prompt uses "quick" but let's also handle "quick_win" if AI slips
347	  let effort: Effort = "moderate";
348	  if (rawEffort === "quick" || rawEffort === "quick_win") effort = "quick";
349	  else if (rawEffort === "significant") effort = "significant";
350	  else if (efforts.includes(rawEffort as Effort)) effort = rawEffort as Effort;
351	
352	  return {
353	    id: typeof f.id === "string" && f.id ? f.id : fallbackId,
354	    title: typeof f.title === "string" ? f.title.slice(0, 120) : "Untitled finding",
355	    severity: severities.includes(rawSeverity as Severity)
356	      ? (rawSeverity as Severity)
357	      : "info",
358	    current_state: typeof f.current_state === "string"
359	      ? f.current_state
360	      : "No details available.",
361	    recommendation: typeof f.recommendation === "string"
362	      ? f.recommendation
363	      : "Review and optimize this element.",
364	    ai_suggestion: typeof f.ai_suggestion === "string"
365	      ? f.ai_suggestion
366	      : "No AI suggestion generated.",
367	    is_premium: typeof f.is_premium === "boolean" ? f.is_premium : false,
368	    effort,
369	    estimated_lift: typeof f.estimated_lift === "string"
370	      ? f.estimated_lift
371	      : "0-1% conversion lift",
372	    category: typeof f.category === "string" ? f.category : "Design",
373	  };
374	}
