1	/**
2	 * pagespeed — Edge Function
3	 *
4	 * Fetches Google PageSpeed Insights data for a given URL and returns
5	 * a structured page_performance pillar result.
6	 *
7	 * Request body: { url: string; strategy?: 'mobile' | 'desktop' }
8	 *
9	 * Response:
10	 * {
11	 *   score: number;           // 0-100 overall performance score
12	 *   findings: Finding[];     // structured CRO findings from metric thresholds
13	 *   metrics: {
14	 *     lcp: number;           // Largest Contentful Paint (ms)
15	 *     cls: number;           // Cumulative Layout Shift (unitless)
16	 *     tbt: number;           // Total Blocking Time (ms, proxy for FID/INP)
17	 *     fcp: number;           // First Contentful Paint (ms)
18	 *     ttfb: number;          // Time to First Byte (ms)
19	 *     speed_index: number;   // Speed Index (ms)
20	 *   }
21	 * }
22	 *
23	 * Required env vars:
24	 *   PAGESPEED_API_KEY — Google Cloud API key with PageSpeed Insights API enabled
25	 */
26	
27	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
28	
29	// ── CORS ──────────────────────────────────────────────────────
30	
31	const corsHeaders = {
32	  "Access-Control-Allow-Origin": "*",
33	  "Access-Control-Allow-Headers":
34	    "authorization, x-client-info, apikey, content-type",
35	  "Access-Control-Allow-Methods": "POST, OPTIONS",
36	};
37	
38	function corsResponse(body: unknown, status = 200) {
39	  return new Response(JSON.stringify(body), {
40	    status,
41	    headers: { ...corsHeaders, "Content-Type": "application/json" },
42	  });
43	}
44	
45	// ── Types ─────────────────────────────────────────────────────
46	
47	type Severity = "critical" | "warning" | "info" | "passed";
48	type Effort = "quick" | "moderate" | "significant";
49	
50	interface Finding {
51	  id: string;
52	  title: string;
53	  severity: Severity;
54	  current_state: string;
55	  recommendation: string;
56	  ai_suggestion: string;
57	  is_premium: boolean;
58	  effort: Effort;
59	  estimated_lift: string;
60	  category: string;
61	}
62	
63	interface PageSpeedMetrics {
64	  lcp: number;
65	  cls: number;
66	  tbt: number;
67	  fcp: number;
68	  ttfb: number;
69	  speed_index: number;
70	}
71	
72	interface PageSpeedResponse {
73	  score: number;
74	  findings: Finding[];
75	  metrics: PageSpeedMetrics;
76	}
77	
78	// ── Handler ───────────────────────────────────────────────────
79	
80	serve(async (req: Request) => {
81	  if (req.method === "OPTIONS") {
82	    return new Response("ok", { headers: corsHeaders });
83	  }
84	
85	  if (req.method !== "POST") {
86	    return corsResponse({ error: "Method not allowed" }, 405);
87	  }
88	
89	  // Parse request body
90	  let url: string;
91	  let strategy: "mobile" | "desktop" = "mobile";
92	  try {
93	    const body = await req.json();
94	    url = body.url;
95	    if (body.strategy === "desktop") strategy = "desktop";
96	    if (!url || typeof url !== "string") {
97	      return corsResponse({ error: "url is required" }, 400);
98	    }
99	    new URL(url); // validate format
100	  } catch (_e) {
101	    return corsResponse({ error: "Invalid request body or URL" }, 400);
102	  }
103	
104	  const apiKey = Deno.env.get("PAGESPEED_API_KEY");
105	  if (!apiKey) {
106	    console.warn("PAGESPEED_API_KEY not configured — returning fallback");
107	    return corsResponse(buildFallbackResponse());
108	  }
109	
110	  // ── Call Google PageSpeed Insights API ─────────────────────
111	  const psUrl = new URL(
112	    "https://www.googleapis.com/pagespeedonline/v5/runPagespeed",
113	  );
114	  psUrl.searchParams.set("url", url);
115	  psUrl.searchParams.set("key", apiKey);
116	  psUrl.searchParams.set("strategy", strategy);
117	  psUrl.searchParams.set("category", "performance");
118	
119	  let psData: Record<string, unknown>;
120	  try {
121	    const res = await fetch(psUrl.toString(), {
122	      signal: AbortSignal.timeout(35_000),
123	    });
124	    if (!res.ok) {
125	      const text = await res.text();
126	      console.error(`PageSpeed API error ${res.status}:`, text.slice(0, 300));
127	      return corsResponse(buildFallbackResponse(), 200); // soft-fail, don't crash scan
128	    }
129	    psData = await res.json();
130	  } catch (e) {
131	    console.error("PageSpeed fetch failed:", e);
132	    return corsResponse(buildFallbackResponse(), 200);
133	  }
134	
135	  const result = parsePageSpeedResponse(psData, strategy);
136	  return corsResponse(result);
137	});
