139	// ── Parser ────────────────────────────────────────────────────
140	
141	interface LighthouseData {
142	  audits?: Record<string, { numericValue?: number; displayValue?: string; score?: number }>;
143	  categories?: Record<string, { score?: number }>;
144	}
145	
146	function parsePageSpeedResponse(
147	  psData: Record<string, unknown>,
148	  _strategy: "mobile" | "desktop",
149	): PageSpeedResponse {
150	  const lhResult = ((psData as { lighthouseResult?: LighthouseData })?.lighthouseResult) ?? {};
151	  const audits = lhResult?.audits ?? {};
152	  const categories = lhResult?.categories ?? {};
153	
154	  const performanceScore = Math.round(
155	    (categories?.performance?.score ?? 0.5) * 100,
156	  );
157	
158	  // Extract raw metric values
159	  const lcpMs: number = audits["largest-contentful-paint"]?.numericValue ?? 0;
160	  const clsVal: number = audits["cumulative-layout-shift"]?.numericValue ?? 0;
161	  const tbtMs: number = audits["total-blocking-time"]?.numericValue ?? 0;
162	  const fcpMs: number = audits["first-contentful-paint"]?.numericValue ?? 0;
163	  const ttfbMs: number = audits["server-response-time"]?.numericValue ?? 0;
164	  const speedIndexMs: number = audits["speed-index"]?.numericValue ?? 0;
165	
166	  const metrics: PageSpeedMetrics = {
167	    lcp: Math.round(lcpMs),
168	    cls: Math.round(clsVal * 1000) / 1000,
169	    tbt: Math.round(tbtMs),
170	    fcp: Math.round(fcpMs),
171	    ttfb: Math.round(ttfbMs),
172	    speed_index: Math.round(speedIndexMs),
173	  };
174	
175	  const findings: Finding[] = [];
176	
177	  // ── LCP ─────────────────────────────────────────────────────
178	  if (lcpMs > 0) {
179	    const lcpSec = (lcpMs / 1000).toFixed(1);
180	    if (lcpMs > 4000) {
181	      findings.push(makeFinding(
182	        "f_pp_lcp",
183	        `LCP is critically slow at ${lcpSec}s — Google classifies as 'Poor'`,
