186	        "1. Identify your LCP element with Chrome DevTools Performance tab. 2. Serve it as WebP. 3. Add <link rel='preload'> for the LCP image. 4. Remove render-blocking CSS/JS above the fold.",
187	        `Add to <head>:\n<link rel="preload" as="image" href="/hero.webp" fetchpriority="high">\n\nConvert your hero image to WebP format (saves 60-80% file size).\n\nSet explicit dimensions on the hero container to eliminate CLS during load:\n<div style="aspect-ratio: 16/9; width: 100%;">`,
188	        false,
189	        "moderate",
190	        "3-6% conversion lift",
191	        "Technical",
192	      ));
193	    } else if (lcpMs > 2500) {
194	      findings.push(makeFinding(
195	        "f_pp_lcp",
196	        `LCP needs improvement at ${lcpSec}s (good: under 2.5s)`,
197	        "warning",
198	        `Your LCP is ${lcpSec}s — in Google's 'Needs Improvement' range (2.5s-4.0s). Main content appears ${(lcpMs - 2500)}ms later than Google's recommended threshold. This delays the moment users see your headline and CTA, increasing early abandonment.`,
199	        "Convert your LCP image to WebP and add a preload hint. Also check for render-blocking stylesheets loaded in <head>.",
200	        `Add to <head>: <link rel="preload" as="image" href="hero.webp">\nConvert PNG/JPG hero to WebP — average savings: 65% file size.\nTarget: get LCP under 2.5s`,
201	        false,
202	        "moderate",
203	        "1-3% conversion lift",
204	        "Technical",
205	      ));
206	    } else {
207	      findings.push(makeFinding(
208	        "f_pp_lcp",
209	        `LCP is excellent at ${lcpSec}s (well under 2.5s threshold)`,
210	        "passed",
211	        `Largest Contentful Paint is ${lcpSec}s — within Google's 'Good' range. Your primary content renders quickly, giving users immediate visual feedback.`,
212	        "Continue monitoring LCP after adding new hero images or loading new scripts.",
213	        "No changes needed. Maintain your current image optimization and preloading strategy.",
214	        false,
215	        "quick",
216	        "0%",
217	        "Technical",
218	      ));
219	    }
220	  }
221	
222	  // ── CLS ─────────────────────────────────────────────────────
223	  if (clsVal >= 0) {
224	    const clsDisplay = clsVal.toFixed(3);
225	    if (clsVal > 0.25) {
226	      findings.push(makeFinding(
227	        "f_pp_cls",
228	        `CLS is critically high at ${clsDisplay} — elements jump during load`,
229	        "critical",
230	        `Cumulative Layout Shift of ${clsDisplay} is in Google's 'Poor' range (> 0.25). Page elements are jumping significantly during load. This causes mis-clicks — users click on what they think is a button, the page shifts, and they click the wrong element. This directly increases frustration and abandonment.`,
