283	    } else if (tbtMs > 200) {
284	      findings.push(makeFinding(
285	        "f_pp_tbt",
286	        `Total Blocking Time needs improvement at ${tbtDisplay}ms`,
287	        "warning",
288	        `TBT of ${tbtDisplay}ms is above Google's 200ms good threshold. JavaScript is blocking the main thread during initial load, creating a window of unresponsiveness.`,
289	        "Defer non-critical third-party scripts and audit for unused JavaScript.",
290	        `Add defer attribute to analytics and marketing scripts.\nDefer the chat widget until after user first interaction.\nTarget: under 200ms TBT`,
291	        false,
292	        "moderate",
293	        "0.5-1% conversion lift",
294	        "Technical",
295	      ));
296	    } else {
297	      findings.push(makeFinding(
298	        "f_pp_tbt",
299	        `Total Blocking Time is excellent at ${tbtDisplay}ms`,
300	        "passed",
301	        `TBT of ${tbtDisplay}ms is well within Google's 'Good' range (< 200ms). The main thread is largely unblocked during load, allowing quick interaction.`,
302	        "Monitor TBT as you add third-party scripts or expand your JavaScript bundle.",
303	        "No changes needed. Continue deferring non-critical JavaScript.",
304	        false,
305	        "quick",
306	        "0%",
307	        "Technical",
308	      ));
309	    }
310	  }
311	
312	  // ── TTFB ─────────────────────────────────────────────────────
313	  if (ttfbMs > 800) {
314	    const ttfbDisplay = Math.round(ttfbMs);
315	    const severity: Severity = ttfbMs > 1800 ? "critical" : "warning";
316	    findings.push(makeFinding(
317	      "f_pp_ttfb",
318	      `Server response time (TTFB) is slow at ${ttfbDisplay}ms`,
319	      severity,
320	      `Time to First Byte of ${ttfbDisplay}ms means your server takes ${(ttfbMs / 1000).toFixed(1)}s just to start sending data — before any HTML is parsed or resources are loaded. Google's good threshold is 800ms. A slow TTFB delays the entire page load chain.`,
321	      "Deploy a CDN (Cloudflare, Vercel Edge) for caching. Optimize server-side processing — check for slow database queries or heavy middleware on initial page render.",
322	      `Quick wins:\n1. Enable Cloudflare proxy — free tier provides global CDN\n2. Add aggressive Cache-Control headers: Cache-Control: public, max-age=3600\n3. Check for database N+1 queries on the page\n4. For Next.js: ensure pages use getStaticProps or ISR where possible`,
323	      true,
324	      "significant",
325	      "1-2% conversion lift",
326	      "Technical",
327	    ));
328	  }
329	
330	  // ── Speed Index ───────────────────────────────────────────────
331	  if (speedIndexMs > 3400) {
332	    const siDisplay = (speedIndexMs / 1000).toFixed(1);
333	    findings.push(makeFinding(
334	      "f_pp_si",
335	      `Speed Index is high at ${siDisplay}s — page fills slowly`,
336	      "warning",
337	      `Speed Index of ${siDisplay}s (good: < 3.4s) measures how quickly content is visually complete. A high Speed Index means users see a partially empty page for an extended period, which signals poor quality and erodes trust even before they've read a word.`,
338	      "Prioritize critical CSS inline, eliminate render-blocking resources, and use SSR or SSG for initial HTML content.",
339	      `1. Inline critical CSS (above-fold styles) in <style> tags in <head>\n2. Remove any render-blocking @import in CSS files\n3. Use font-display: swap to prevent invisible text\n4. Ensure server-rendered HTML includes visible content (not empty shell for SPAs)`,
340	      true,
341	      "moderate",
342	      "0.5-1% conversion lift",
343	      "Technical",
344	    ));
345	  }
346	
347	  // ── FCP note if it's slow ────────────────────────────────────
348	  if (fcpMs > 1800) {
349	    const fcpDisplay = (fcpMs / 1000).toFixed(1);
350	    findings.push(makeFinding(
351	      "f_pp_fcp",
352	      `First Contentful Paint is slow at ${fcpDisplay}s (good: under 1.8s)`,
353	      fcpMs > 3000 ? "warning" : "info",
354	      `FCP of ${fcpDisplay}s — the first moment ANY content appears — is above Google's 1.8s 'Good' threshold. Users see a blank page for ${fcpDisplay}s before anything renders. A blank page increases abandonment by 32% compared to seeing content within 1s.`,
355	      "Eliminate render-blocking resources. Inline critical CSS. Ensure the server sends HTML with visible content immediately.",
356	      `Remove render-blocking resources from <head>.\nInline styles for above-the-fold content.\nDefer or async all JavaScript in <head>.\nTarget: FCP under 1.8s`,
357	      false,
358	      "moderate",
359	      "0.5-1% conversion lift",
360	      "Technical",
361	    ));
362	  }
363	
364	  // If findings is empty (very fast page), add a passed finding
365	  if (findings.length === 0) {
366	    findings.push(makeFinding(
367	      "f_pp_excellent",
368	      "Page performance is excellent across all Core Web Vitals",
369	      "passed",
370	      `All Core Web Vitals are in Google's 'Good' range. PageSpeed score: ${performanceScore}/100. Your page loads fast, stays stable, and responds quickly — a competitive advantage.`,
371	      "Monitor performance over time with continuous Lighthouse CI. Performance can degrade as features are added.",
372	      "Set up Lighthouse CI in your GitHub Actions pipeline to catch regressions before they reach production.",
373	      false,
374	      "quick",
375	      "0%",
376	      "Technical",
377	    ));
378	  }
379	
380	  return { score: performanceScore, findings, metrics };
381	}
