2	 * dodo-webhook — Edge Function
3	 *
4	 * Handles incoming Dodo Payments webhook events and keeps the profiles table
5	 * in sync with subscription state.
6	 *
7	 * Handled events:
8	 *   subscription.active          → activate plan, set scan_limit, billing_cycle_end
9	 *   subscription.renewed         → update billing_cycle_end
10	 *   subscription.cancelled       → downgrade to free, clear billing data
11	 *   subscription.on_hold         → log for observability
12	 *   payment.failed               → log for observability
13	 *   subscription.charge_failed   → log for observability
14	 *
15	 * Required env vars:
16	 *   DODO_WEBHOOK_SECRET          (from Dodo Payments dashboard → webhook endpoint)
17	 *   DODO_PRODUCT_PRO_MONTHLY
18	 *   DODO_PRODUCT_PRO_ANNUAL
19	 *   DODO_PRODUCT_AGENCY_MONTHLY
20	 *   DODO_PRODUCT_AGENCY_ANNUAL
21	 *   SUPABASE_URL
22	 *   SUPABASE_SERVICE_ROLE_KEY
23	 *
24	 * Security: Webhook signature is verified via standardwebhooks before any processing.
25	 */
26	
27	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
28	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
29	import { Webhook } from "https://esm.sh/standardwebhooks@1.0.0";
30	
31	// ── Plan config ───────────────────────────────────────────────────
32	
33	type PlanType = "free" | "pro" | "agency";
34	
35	const PLAN_LIMITS: Record<PlanType, number> = {
36	  free: 3,
37	  pro: 50,
38	  agency: 500,
39	};
40	
41	function getPlanFromProductId(productId: string): PlanType {
42	  const proMonthly = Deno.env.get("DODO_PRODUCT_PRO_MONTHLY");
43	  const proAnnual = Deno.env.get("DODO_PRODUCT_PRO_ANNUAL");
44	  const agencyMonthly = Deno.env.get("DODO_PRODUCT_AGENCY_MONTHLY");
45	  const agencyAnnual = Deno.env.get("DODO_PRODUCT_AGENCY_ANNUAL");
46	
47	  if (productId === proMonthly || productId === proAnnual) return "pro";
48	  if (productId === agencyMonthly || productId === agencyAnnual) return "agency";
49	
50	  console.warn(`Unknown product ID: ${productId}. Defaulting to 'pro'.`);
51	  return "pro";
52	}
53	
54	// ── Serve ─────────────────────────────────────────────────────────
55	
56	serve(async (req: Request) => {
57	  const body = await req.text();
58	
59	  const webhookSecret = Deno.env.get("DODO_WEBHOOK_SECRET");
60	  if (!webhookSecret) {
61	    console.error("DODO_WEBHOOK_SECRET env var not set");
62	    return new Response(
63	      JSON.stringify({ error: "Webhook secret not configured" }),
64	      { status: 500, headers: { "Content-Type": "application/json" } }
65	    );
66	  }
67	
68	  // ── Verify signature (standardwebhooks) ──────────────────────────
69	  let event: { type: string; data: Record<string, unknown> };
70	
71	  try {
72	    const wh = new Webhook(webhookSecret);
73	    const headers = {
74	      "webhook-id": req.headers.get("webhook-id") ?? "",
75	      "webhook-timestamp": req.headers.get("webhook-timestamp") ?? "",
76	      "webhook-signature": req.headers.get("webhook-signature") ?? "",
77	    };
78	    event = wh.verify(body, headers) as { type: string; data: Record<string, unknown> };
79	  } catch (err: unknown) {
80	    const message = err instanceof Error ? err.message : "Invalid signature";
81	    console.error("Webhook signature verification failed:", message);
82	    return new Response(
83	      JSON.stringify({ error: `Webhook verification failed: ${message}` }),
84	      { status: 400, headers: { "Content-Type": "application/json" } }
85	    );
86	  }
87	
88	  // ── Admin Supabase client (bypasses RLS) ─────────────────────────
89	  const supabase = createClient(
90	    Deno.env.get("SUPABASE_URL") ?? "",
91	    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
92	  );
93	
94	  // ── Event routing ─────────────────────────────────────────────────
95	  try {
96	    switch (event.type) {
97	      // ── subscription.active ──────────────────────────────────────
98	      // Fires when a new subscription is created and payment succeeds.
99	      case "subscription.active": {
100	        const sub = event.data as {
101	          subscription_id: string;
102	          customer_id: string;
103	          product_id: string;
104	          current_period_end?: number;
105	          metadata?: Record<string, string>;
106	        };
107	
108	        const userId = sub.metadata?.user_id;
109	        const plan = (sub.metadata?.plan ?? getPlanFromProductId(sub.product_id)) as PlanType;
110	
111	        if (!userId) {
112	          console.error("subscription.active: missing user_id in metadata");
113	          break;
114	        }
115	
116	        const billingCycleEnd = sub.current_period_end
117	          ? new Date(sub.current_period_end * 1000).toISOString()
118	          : null;
119	
120	        const { error } = await supabase
121	          .from("profiles")
122	          .update({
123	            plan,
124	            scan_limit: PLAN_LIMITS[plan] ?? PLAN_LIMITS.pro,
125	            scans_used: 0, // reset usage counter when plan activates
126	            dodo_subscription_id: sub.subscription_id,
127	            dodo_customer_id: sub.customer_id,
128	            billing_cycle_end: billingCycleEnd,
129	            updated_at: new Date().toISOString(),
130	          })
131	          .eq("id", userId);
132	
133	        if (error) {
134	          console.error("subscription.active profile update error:", error);
135	        } else {
136	          console.log(`Activated ${plan} plan for user ${userId}`);
137	        }
138	        break;
139	      }
140	
141	      // ── subscription.renewed ─────────────────────────────────────
142	      // Fires on each successful renewal cycle.
143	      case "subscription.renewed": {
144	        const sub = event.data as {
145	          subscription_id: string;
146	          customer_id: string;
147	          product_id: string;
148	          current_period_end?: number;
149	        };
150	
151	        const { data: profile, error: profileError } = await supabase
152	          .from("profiles")
153	          .select("id, plan")
154	          .eq("dodo_customer_id", sub.customer_id)
155	          .single();
156	
157	        if (profileError || !profile) {
158	          console.error(
159	            "subscription.renewed: profile not found for customer",
160	            sub.customer_id
161	          );
162	          break;
163	        }
164	
165	        const billingCycleEnd = sub.current_period_end
166	          ? new Date(sub.current_period_end * 1000).toISOString()
167	          : null;
168	
169	        const { error } = await supabase
170	          .from("profiles")
171	          .update({
172	            dodo_subscription_id: sub.subscription_id,
173	            billing_cycle_end: billingCycleEnd,
174	            scans_used: 0, // reset usage counter on each billing cycle renewal
175	            updated_at: new Date().toISOString(),
176	          })
177	          .eq("id", profile.id);
178	
179	        if (error) {
180	          console.error("subscription.renewed profile update error:", error);
181	        } else {
182	          console.log(`Renewed subscription for user ${profile.id}, scan usage reset`);
183	        }
184	        break;
185	      }
186	
187	      // ── subscription.cancelled ───────────────────────────────────
188	      // Fires when a subscription is cancelled (immediately or at period end).
189	      case "subscription.cancelled": {
190	        const sub = event.data as {
191	          subscription_id: string;
192	          customer_id: string;
193	        };
194	
195	        const { data: profile, error: profileError } = await supabase
196	          .from("profiles")
197	          .select("id")
198	          .eq("dodo_customer_id", sub.customer_id)
199	          .single();
200	
201	        if (profileError || !profile) {
202	          console.error(
203	            "subscription.cancelled: profile not found for customer",
204	            sub.customer_id
205	          );
206	          break;
207	        }
208	
209	        const { error } = await supabase
210	          .from("profiles")
211	          .update({
212	            plan: "free",
213	            scan_limit: PLAN_LIMITS.free,
214	            dodo_subscription_id: null,
215	            billing_cycle_end: null,
216	            updated_at: new Date().toISOString(),
217	          })
218	          .eq("id", profile.id);
219	
220	        if (error) {
221	          console.error("subscription.cancelled profile update error:", error);
222	        } else {
223	          console.log(`Downgraded user ${profile.id} to free plan (subscription cancelled)`);
224	        }
225	        break;
226	      }
227	
228	      // ── subscription.on_hold / payment.failed ────────────────────
229	      case "subscription.on_hold":
230	      case "payment.failed":
231	      case "subscription.charge_failed": {
232	        const data = event.data as {
233	          customer_id?: string;
234	          subscription_id?: string;
235	        };
236	        console.log(
237	          `${event.type} for customer ${data.customer_id ?? "unknown"}, subscription ${data.subscription_id ?? "unknown"}`
238	        );
239	        // Future: trigger a dunning email via send-email function
240	        break;
241	      }
242	
243	      default:
244	        console.log(`Unhandled webhook event type: ${event.type}`);
245	    }
246	
247	    return new Response(
248	      JSON.stringify({ received: true }),
249	      { status: 200, headers: { "Content-Type": "application/json" } }
250	    );
251	  } catch (error: unknown) {
252	    const message = error instanceof Error ? error.message : "Handler error";
253	    console.error(`Error handling ${event.type}:`, error);
254	    return new Response(
255	      JSON.stringify({ error: message }),
256	      { status: 500, headers: { "Content-Type": "application/json" } }
257	    );
258	  }
259	});
260

1	/**
2	 * dodo-checkout — Edge Function
3	 *
4	 * Creates a Dodo Payments subscription checkout session for plan upgrades.
5	 *
6	 * Expected request body:
7	 *   { plan: 'pro' | 'agency'; billing_cycle: 'monthly' | 'annual' }
8	 *
9	 * Returns:
10	 *   { url: string } — Dodo-hosted checkout page URL
11	 *
12	 * Required env vars:
13	 *   DODO_API_KEY
14	 *   DODO_PRODUCT_PRO_MONTHLY
15	 *   DODO_PRODUCT_PRO_ANNUAL
16	 *   DODO_PRODUCT_AGENCY_MONTHLY
17	 *   DODO_PRODUCT_AGENCY_ANNUAL
18	 *   SITE_URL
19	 *   SUPABASE_URL
20	 *   SUPABASE_ANON_KEY
21	 *   SUPABASE_SERVICE_ROLE_KEY
22	 */
23	
24	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
25	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
26	
27	const corsHeaders = {
28	  "Access-Control-Allow-Origin": "*",
29	  "Access-Control-Allow-Headers":
30	    "authorization, x-client-info, apikey, content-type",
31	};
32	
33	function getProductId(plan: string, billingCycle: string): string | null {
34	  const map: Record<string, string> = {
35	    "pro:monthly": Deno.env.get("DODO_PRODUCT_PRO_MONTHLY") ?? "",
36	    "pro:annual": Deno.env.get("DODO_PRODUCT_PRO_ANNUAL") ?? "",
37	    "agency:monthly": Deno.env.get("DODO_PRODUCT_AGENCY_MONTHLY") ?? "",
38	    "agency:annual": Deno.env.get("DODO_PRODUCT_AGENCY_ANNUAL") ?? "",
39	  };
40	  return map[`${plan}:${billingCycle}`] || null;
41	}
42	
43	serve(async (req: Request) => {
44	  if (req.method === "OPTIONS") {
45	    return new Response("ok", { headers: corsHeaders });
46	  }
47	
48	  try {
49	    // ── 1. Auth ──────────────────────────────────────────────────────
50	    const authHeader = req.headers.get("Authorization");
51	    if (!authHeader) {
52	      return new Response(
53	        JSON.stringify({ error: "Missing Authorization header" }),
54	        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
55	      );
56	    }
57	
58	    const supabaseUser = createClient(
59	      Deno.env.get("SUPABASE_URL") ?? "",
60	      Deno.env.get("SUPABASE_ANON_KEY") ?? "",
61	      { global: { headers: { Authorization: authHeader } } }
62	    );
63	
64	    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
65	    if (userError || !user) {
66	      return new Response(
67	        JSON.stringify({ error: "Unauthorized" }),
68	        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
69	      );
70	    }
71	
72	    // ── 2. Parse + validate body ─────────────────────────────────────
73	    let body: { plan?: string; billing_cycle?: string };
74	    try {
75	      body = await req.json();
76	    } catch {
77	      return new Response(
78	        JSON.stringify({ error: "Invalid JSON body" }),
79	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
80	      );
81	    }
82	
83	    const { plan, billing_cycle } = body;
84	
85	    if (!plan || !["pro", "agency"].includes(plan)) {
86	      return new Response(
87	        JSON.stringify({ error: "Invalid plan. Must be 'pro' or 'agency'." }),
88	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
89	      );
90	    }
91	
92	    if (!billing_cycle || !["monthly", "annual"].includes(billing_cycle)) {
93	      return new Response(
94	        JSON.stringify({ error: "Invalid billing_cycle. Must be 'monthly' or 'annual'." }),
95	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
96	      );
97	    }
98	
99	    const productId = getProductId(plan, billing_cycle);
100	    if (!productId) {
101	      console.error(`Missing product ID for ${plan}:${billing_cycle}`);
102	      return new Response(
103	        JSON.stringify({ error: "Pricing configuration error. Contact support." }),
104	        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
105	      );
106	    }
107	
108	    // ── 3. Get user profile ──────────────────────────────────────────
109	    const supabaseAdmin = createClient(
110	      Deno.env.get("SUPABASE_URL") ?? "",
111	      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
112	    );
113	
114	    const { data: profile, error: profileError } = await supabaseAdmin
115	      .from("profiles")
116	      .select("id, email, full_name, dodo_customer_id")
117	      .eq("id", user.id)
118	      .single();
119	
120	    if (profileError || !profile) {
121	      console.error("Profile fetch error:", profileError);
122	      return new Response(
123	        JSON.stringify({ error: "User profile not found." }),
124	        { status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" } }
125	      );
126	    }
127	
128	    // ── 4. Build Dodo customer payload ───────────────────────────────
129	    const customerPayload = profile.dodo_customer_id
130	      ? { create_new_customer: false, customer_id: profile.dodo_customer_id }
131	      : {
132	          create_new_customer: true,
133	          email: profile.email ?? user.email,
134	          name: profile.full_name ?? "",
135	        };
136	
137	    const origin = Deno.env.get("SITE_URL") ?? "http://localhost:5173";
138	    const dodoApiKey = Deno.env.get("DODO_API_KEY") ?? "";
139	
140	    // ── 5. Create subscription checkout with payment link ────────────
141	    const dodoRes = await fetch("https://api.dodopayments.com/subscriptions", {
142	      method: "POST",
143	      headers: {
144	        "Authorization": `Bearer ${dodoApiKey}`,
145	        "Content-Type": "application/json",
146	      },
147	      body: JSON.stringify({
148	        billing: {
149	          currency: "USD",
150	          interval: billing_cycle === "annual" ? "year" : "month",
151	          interval_count: 1,
152	        },
153	        customer: customerPayload,
154	        product_id: productId,
155	        payment_link: true,
156	        return_url: `${origin}/dashboard?checkout=success`,
157	        metadata: {
158	          user_id: user.id,
159	          plan,
160	        },
161	      }),
162	    });
163	
164	    if (!dodoRes.ok) {
165	      const errText = await dodoRes.text();
166	      console.error("Dodo API error:", dodoRes.status, errText);
167	      return new Response(
168	        JSON.stringify({ error: "Failed to create checkout session." }),
169	        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
170	      );
171	    }
172	
173	    const dodoData = await dodoRes.json();
174	
175	    // Persist customer ID if newly created
176	    if (!profile.dodo_customer_id && dodoData.customer_id) {
177	      const { error: updateError } = await supabaseAdmin
178	        .from("profiles")
179	        .update({ dodo_customer_id: dodoData.customer_id })
180	        .eq("id", user.id);
181	
182	      if (updateError) {
183	        // Non-fatal — will be captured via webhook
184	        console.error("Failed to persist dodo_customer_id:", updateError);
185	      }
186	    }
187	
188	    const checkoutUrl = dodoData.payment_link;
189	    if (!checkoutUrl) {
190	      console.error("No payment_link in Dodo response:", dodoData);
191	      return new Response(
192	        JSON.stringify({ error: "No checkout URL returned from payment provider." }),
193	        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
194	      );
195	    }
196	
197	    return new Response(
198	      JSON.stringify({ url: checkoutUrl }),
199	      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
200	    );
201	  } catch (error: unknown) {
202	    const message = error instanceof Error ? error.message : "Internal server error";
203	    console.error("dodo-checkout error:", error);
204	    return new Response(
205	      JSON.stringify({ error: message }),
206	      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
207	    );
208	  }
209	});
